from collections import defaultdict, deque
R,C=len(g),len(g[0]); seen=set(); comps=[]
for r in range(R):
 for c in range(C):
  col=g[r][c]
  if col==9 or (r,c) in seen: continue
  q=[(r,c)]; seen.add((r,c)); cells=[]
  while q:
   x,y=q.pop(); cells.append((x,y))
   for dx,dy in ((1,0),(-1,0),(0,1),(0,-1)):
    z=(x+dx,y+dy)
    if 0<=z[0]<R and 0<=z[1]<C and z not in seen and g[z[0]][z[1]]==col:
     seen.add(z);q.append(z)
  comps.append((col,cells))
def norm(cells):
 r0=min(r for r,c in cells); c0=min(c for r,c in cells)
 return tuple(sorted((r-r0,c-c0) for r,c in cells))
