  a=[]
  for r,c in pts:
   if k>=4: c=-c
   for _ in range(k%4): r,c=c,-r
   a.append((r,c))
  mr=min(r for r,c in a);mc=min(c for r,c in a)
  result.append(tuple(sorted((r-mr,c-mc) for r,c in a)))
 return result
